const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { satisfies, compare, parse } = require('./src/semver');

// semver
assert.equal(satisfies('0.2.9', '^0.2.3'), true);
assert.equal(satisfies('0.3.0', '^0.2.3'), false);
assert.equal(satisfies('0.0.3', '^0.0.3'), true);
assert.equal(satisfies('0.0.4', '^0.0.3'), false);
assert.equal(satisfies('1.9.0', '^1.2.3'), true);
assert.equal(satisfies('2.0.0', '^1.2.3'), false);
assert.equal(satisfies('1.2.9', '~1.2.3'), true);
assert.equal(satisfies('1.3.0', '~1.2.3'), false);
assert.equal(compare('1.10.0', '1.9.0'), 1);
assert.throws(() => parse('01.0.0'), TypeError);
assert.throws(() => satisfies('1.0.0', ''), TypeError);

// Naive spec reference (no pruning), recursive; small inputs only.
function reference(registry, root) {
  const cat = new Map(Object.keys(registry).map(n => [n, Object.keys(registry[n])
    .sort((a, b) => compare(b, a))]));
  function go(selected, constraints, queue, cursor) {
    while (cursor < queue.length && selected.has(queue[cursor])) cursor++;
    if (cursor === queue.length) return Object.fromEntries(selected);
    const name = queue[cursor];
    const cands = (cat.get(name) || []).filter(v => (constraints.get(name) || []).every(r => satisfies(v, r)));
    for (const v of cands) {
      const s = new Map(selected); s.set(name, v);
      const c = new Map([...constraints].map(([k, l]) => [k, [...l]]));
      const q = [...queue]; let ok = true;
      for (const [d, r] of Object.entries(registry[name][v])) {
        q.push(d); if (!c.has(d)) c.set(d, []); c.get(d).push(r);
        if (s.has(d) && !satisfies(s.get(d), r)) { ok = false; break; }
      }
      if (!ok) continue;
      const res = go(s, c, q, cursor + 1);
      if (res) return res;
    }
    return null;
  }
  const c = new Map(); const q = [];
  for (const [d, r] of Object.entries(root)) { q.push(d); c.set(d, [r]); }
  return go(new Map(), c, q, 0);
}

